    col_seps = {c for c in range(w) if all(grid[r][c] == 8 for r in range(h))}
    row_blocks, col_blocks = [], []
    start = 0
    for r in sorted(row_seps) + [h]:
        if start < r:
            row_blocks.append(list(range(start, r)))
        start = r + 1
    start = 0
    for c in sorted(col_seps) + [w]:
        if start < c:
            col_blocks.append(list(range(start, c)))
        start = c + 1

    # Read the colored markers by their compartment coordinates.
    markers = {}
    for br, rs in enumerate(row_blocks):
        for bc, cs in enumerate(col_blocks):
            for r in rs:
                for c in cs:
                    color = grid[r][c]
                    if color not in (0, 8):
                        markers.setdefault(color, []).append((br, bc))

    painted = {}
    for color, points in markers.items():
        row_counts = Counter(r for r, _ in points)
        col_counts = Counter(c for _, c in points)
        rows = {r for r, n in row_counts.items() if n >= 2}
        cols = {c for c, n in col_counts.items() if n >= 2}
        for br in range(len(row_blocks)):
            for bc in range(len(col_blocks)):
                if br in rows or bc in cols:
                    painted.setdefault((br, bc), set()).add(color)

    out = [row[:] for row in grid]
    for (br, bc), colors in painted.items():
        # The observed intersection of colors 2 and 3 is represented by 6.
        fill = 6 if 2 in colors and 3 in colors else min(colors)
        for r in row_blocks[br]:
            for c in col_blocks[bc]:
                out[r][c] = fill
    return out


